<h2>Student.java</h2>
<pre class="lang-java prettyprint-override"><code>package com.example.entity.anag;

import jakarta.persistence.*;
import lombok.AllArgsConstructor;
import lombok.Builder;
import lombok.Data;
import lombok.NoArgsConstructor;

import java.time.LocalDate;

@Data
@NoArgsConstructor
@AllArgsConstructor
@Builder
@Entity
@Table(name = &quot;student&quot;)
public class Student {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Integer id;

    @Column(length = 100, nullable = false)
    private String name;

    @Column(name = &quot;birth_date&quot;)
    private LocalDate birthDate;

    @Column(length = 100)
    private String email;

    @Column(length = 2)
    private String grade;

    @Column(name = &quot;enrollment_date&quot;)
    private LocalDate enrollmentDate;
}
</code></pre>
<h2>StudentRepository.java</h2>
<pre class="lang-java prettyprint-override"><code>package com.example.repo.anag;

import com.example.entity.anag.Student;
import org.springframework.data.jpa.repository.JpaRepository;

import java.util.List;

public interface StudentRepository extends JpaRepository&lt;Student, Integer&gt; {
    List&lt;Student&gt; findByName(String name);
}
</code></pre>
<h2>StudentService.java</h2>
<pre class="lang-java prettyprint-override"><code>package com.example.service.anag;

import com.example.entity.anag.Student;
import com.example.repo.anag.StudentRepository;
import lombok.RequiredArgsConstructor;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;
import java.util.Optional;

@Service
@RequiredArgsConstructor
@Transactional(transactionManager = &quot;anagTransactionManager&quot;)
public class StudentService {

    private final StudentRepository repo;

    public List&lt;Student&gt; listAll() {
        return repo.findAll();
    }

    public Optional&lt;Student&gt; findById(Integer id) {
        return repo.findById(id);
    }

    public List&lt;Student&gt; findByName(String name) {
        return repo.findByName(name);
    }

    public Student create(Student student) {
        return repo.save(student);
    }

    public Student update(Integer id, Student student) {
        return repo.findById(id)
                .map(s -&gt; {
                    s.setName(student.getName());
                    s.setBirthDate(student.getBirthDate());
                    s.setEmail(student.getEmail());
                    s.setGrade(student.getGrade());
                    s.setEnrollmentDate(student.getEnrollmentDate());
                    return repo.save(s);
                })
                .orElseThrow(() -&gt; new RuntimeException(&quot;Student ID not found: &quot; + id));
    }

    public void delete(Integer id) {
        repo.deleteById(id);
    }
}
</code></pre>
<h2>StudentController.java</h2>
<pre class="lang-java prettyprint-override"><code>package com.example.controller.anag;

import com.example.entity.anag.Student;
import com.example.service.anag.StudentService;
import lombok.RequiredArgsConstructor;
import org.springframework.web.bind.annotation.*;

import java.util.List;

@RestController
@RequiredArgsConstructor
@RequestMapping(&quot;/api/anag/students&quot;)
public class StudentController {

    private final StudentService service;

    @GetMapping
    public List&lt;Student&gt; listAll() {
        return service.listAll();
    }

    @GetMapping(&quot;/{id}&quot;)
    public Student findById(@PathVariable Integer id) {
        return service.findById(id).orElse(null);
    }

    @GetMapping(&quot;/name/{name}&quot;)
    public List&lt;Student&gt; findByName(@PathVariable String name) {
        return service.findByName(name);
    }

    // CREATE
    @PostMapping
    public Student create(@RequestBody Student student) {
        return service.create(student);
    }

    // UPDATE
    @PutMapping(&quot;/{id}&quot;)
    public Student update(@PathVariable Integer id, @RequestBody Student student) {
        return service.update(id, student);
    }

    // DELETE
    @DeleteMapping(&quot;/{id}&quot;)
    public void delete(@PathVariable Integer id) {
        service.delete(id);
    }
}
</code></pre>
